"""Calls generated by public pytest hooks preserve aliases through native packing."""

from __future__ import annotations

import json
from pathlib import Path

import pytest

from tests.integration.test_native_parallel import _native_parallel_available
from tests.support import VfyProject

pytestmark = pytest.mark.skipif(
    not _native_parallel_available(),
    reason="native collection requires Unix and a supported pytest version",
)


def test_packed_generation_preserves_all_container_aliases_and_value_release(
    tmp_path: Path,
) -> None:
    source = """\
import json
import os
from pathlib import Path
from _pytest.python import CallSpec2

saved_vars = None
saved_containers = None
saved_calls = None
released = []
fields = ('params', 'indices', '_arg2scope', '_idlist', 'marks')

class Value:
    def __init__(self, name):
        self.name = name

    def __del__(self):
        # Re-enter the callspec adapter after the last real parameter reference
        # disappears. A native borrow must not survive container mutation.
        assert saved_calls[-1].id
        released.append(self.name)

def pytest_generate_tests(metafunc):
    global saved_vars, saved_containers, saved_calls
    if metafunc.function.__name__ == 'test_primitive_control':
        # ID callbacks retain canonical generation before the batch packer.
        metafunc.parametrize('value', [10, 11], ids=lambda value: f'primitive-{value}')
        return
    metafunc.parametrize('value', [Value('raw'), Value('aliased'), Value('dense')])
    saved_calls = metafunc._calls[:]
    saved_vars = vars(saved_calls[0])
    saved_containers = {name: getattr(saved_calls[1], name) for name in fields}

def observe_collection(items):
    assert len(items) == 5
    value_items = [item for item in items if item.originalname == 'test_case']
    controls = [item for item in items if item.originalname == 'test_primitive_control']
    assert len(value_items) == 3 and len(controls) == 2
    calls = [item.callspec for item in value_items]
    assert all(type(call) is CallSpec2 for call in calls)
    assert all(call is saved for call, saved in zip(calls, saved_calls))
    assert vars(calls[0]) is saved_vars
    assert all(getattr(calls[1], name) is value for name, value in saved_containers.items())
    for index, call in enumerate(calls):
        params = call.params
        del params['value']
        assert released == ['raw', 'aliased', 'dense'][:index + 1]
        params['value'] = f'replaced-{index}'
    observed = [[call.id, list(vars(call)), call.params] for call in calls]
    Path('observed.json').write_text(json.dumps([released, observed]))
"""
    observations = {}
    for route in ("pytest", "native"):
        project = VfyProject(tmp_path / route)
        project.write(
            "conftest.py",
            "def pytest_collection_modifyitems(items):\n"
            "    from test_cases import observe_collection\n"
            "    observe_collection(items)\n",
        )
        project.write(
            "test_cases.py",
            source
            + "\ndef test_case(value):\n    assert value.startswith('replaced-')\n"
            + "\ndef test_primitive_control(value):\n    assert value in (10, 11)\n",
        )
        environment = {
            "PACK_ROUTE": route,
            "VFY_NATIVE_SCHEDULING": "cases",
        }
        result = (
            project.run_pytest("-q", load_xdist=False, env=environment)
            if route == "pytest"
            else project.run_vfy(
                "test",
                "--engine=pytest-native",
                "--workers=2",
                "--no-replay",
                "--no-cov",
                "-q",
                env=environment,
            )
        )
        assert result.returncode == 0, result.stdout + result.stderr
        assert "5 passed" in result.stdout
        observations[route] = json.loads((project.root / "observed.json").read_text())
    assert observations["native"] == observations["pytest"]


@pytest.mark.parametrize("getter", ["id", "getattribute", "id_late"])
def test_generate_callback_getter_replacements_are_observed(tmp_path: Path, getter: str) -> None:
    source = """\
import json
from pathlib import Path
from _pytest.python import CallSpec2, Class

seen = []
original = CallSpec2.__getattribute__

def replacement_id(self):
    seen.append('id')
    return 'custom-' + '-'.join(self._idlist)

def replacement_attribute(self, name):
    if name == 'id':
        seen.append('attribute')
    return original(self, name)

def pytest_generate_tests(metafunc):
    metafunc.parametrize('value', [0, 1])
    if GETTER == 'id':
        CallSpec2.id = property(replacement_id)
    elif GETTER == 'getattribute':
        CallSpec2.__getattribute__ = replacement_attribute
    else:
        # Class instance creation follows each case's name selection and can
        # customize the getter between two rows of an already packed family.
        create = Class.newinstance
        def newinstance(self):
            CallSpec2.id = property(replacement_id)
            return create(self)
        Class.newinstance = newinstance

def observe_collection(session):
    Path('observed.json').write_text(json.dumps([
        [item.nodeid for item in session.items], bool(seen),
    ]))
""".replace("GETTER", repr(getter))
    observations = {}
    for route in ("pytest", "native"):
        project = VfyProject(tmp_path / route)
        project.write(
            "conftest.py",
            "def pytest_collection_finish(session):\n"
            "    from test_cases import observe_collection\n"
            "    observe_collection(session)\n",
        )
        project.write(
            "test_cases.py",
            source
            + "\n"
            + (
                "class TestCases:\n    def test_case(self, value):\n"
                "        assert value in [0, 1]\n"
                if getter == "id_late"
                else "def test_case(value):\n    assert value in [0, 1]\n"
            ),
        )
        environment = {
            "VFY_NATIVE_SCHEDULING": "cases",
        }
        result = (
            project.run_pytest("-q", load_xdist=False, env=environment)
            if route == "pytest"
            else project.run_vfy(
                "test",
                "--engine=pytest-native",
                "--workers=2",
                "--no-replay",
                "--no-cov",
                "-q",
                env=environment,
            )
        )
        assert result.returncode == 0, result.stdout + result.stderr
        assert "2 passed" in result.stdout
        observations[route] = json.loads((project.root / "observed.json").read_text())
    assert observations["native"] == observations["pytest"]
    assert observations["native"][1] is True
